    lines_i += 1
    if sep is None:
        return conv(line)
    else:
        return [conv(token) for token in line.split(sep)]


def solve(P, N):
    max1, max2 = (0, 1) if P[0] >= P[1] else (1, 0)
    for i in range(2, N):
        if P[i] > P[max1]:
            max2 = max1
            max1 = i
        elif P[i] > P[max2]:
            max2 = i
    A = ord('A')
    R = [chr(A+max1)] * (P[max1]-P[max2])
    for i in range(N):
        if i == max1 or i == max2:
            continue
        R += [chr(A+i)] * P[i]
    R += [chr(A+max1) + chr(A+max2)] * P[max2]
    return R


