import sys

def deal(n, a):
    o = []
    e = []
    for i in range(len(a)):
        if ((i%2) == 0):
            e.append(int(a[i]))
        else:
            o.append(int(a[i]))
    o.sort()
    e.sort()
    o_i = 0
    e_i = 0
    for i in range(len(a)-1):
        if ((i%2) == 0):
            if e[e_i] > o[o_i]:
                return i
            e_i += 1
        else:
            if o[o_i] > e[e_i]:
                return i
            o_i += 1
    return -1


